// Generate the Unicode 17.0 normalization cases with the repository's exact
// Node oracle from .tool-versions. This script is tooling only; nts never builds or runs it.
//
// node tooling/unicode-cases/normalization.ts [--data-dir=/path/to/ucd] [--output-dir=/path] [--check]
// Without --data-dir, the hash-pinned official input is fetched in memory.
// --check compares every generated byte and the complete filename inventory.
// Existing differing cases are never overwritten: recorded cases are immutable.
// When reviewing a Unicode or ICU upgrade, update its version and hash constants together,
// then use a clean --output-dir to inspect new cases without changing old ones.

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const UNICODE = "17.0";
const ICU = "78.3";
const DATA_VERSION = "17.0.0";
const SOURCE = "https://www.unicode.org/Public/17.0.0/ucd/NormalizationTest.txt";
const SHA256 = "5019ffd530751a741900c849c0e010332f142a3612234639bd200b82138a87db";
const ROOT = resolve(import.meta.dirname, "../..");
const nodeEntries = readFileSync(join(ROOT, ".tool-versions"), "utf8").split(/\r?\n/)
  .map(line => line.split("#")[0].trim()).filter(line => /^nodejs(?:\s|$)/.test(line));
const nodeMatch = nodeEntries.length === 1 ? /^nodejs\s+(\d+\.\d+\.\d+)$/.exec(nodeEntries[0]) : null;
if (nodeMatch === null) throw new Error(".tool-versions must contain exactly one pinned nodejs x.y.z version; no files written");
const NODE = nodeMatch[1];
const OUTPUT = join(ROOT, "tests/typescript/unicode");
const PREFIX = "normalization-";
const CHUNK_ROWS = 256;
const BLOCK_SIZE = 4096;
const PLANE_SIZE = 65536;
type Form = "NFC" | "NFD" | "NFKC" | "NFKD";
const FORMS: Form[] = ["NFC", "NFD", "NFKC", "NFKD"];
type Row = { part: number; line: number; columns: [string, string, string, string, string] };
type Options = { check: boolean; dataDir: string | undefined; outputDir: string };

function requireOracle(): void {
  if (process.versions.node !== NODE || process.versions.unicode !== UNICODE || process.versions.icu !== ICU) {
    throw new Error(`Normalization generator requires Node ${NODE}, Unicode ${UNICODE}, ICU ${ICU}; ` +
      `found Node ${process.versions.node}, Unicode ${process.versions.unicode}, ICU ${process.versions.icu}`);
  }
}

function options(): Options {
  let check = false;
  let dataDir: string | undefined;
  let outputDir = OUTPUT;
  for (const argument of process.argv.slice(2)) {
    if (argument === "--check") check = true;
    else if (argument.startsWith("--data-dir=") && argument.length > 11) dataDir = resolve(argument.slice(11));
    else if (argument.startsWith("--output-dir=") && argument.length > 13) outputDir = resolve(argument.slice(13));
    else throw new Error(`Unknown argument ${argument}`);
  }
  return { check, dataDir, outputDir };
}

async function sourceText(dataDir: string | undefined): Promise<string> {
  let bytes: Uint8Array;
  if (dataDir !== undefined) bytes = readFileSync(join(dataDir, "NormalizationTest.txt"));
  else {
    const response = await fetch(SOURCE);
    if (!response.ok) throw new Error(`Fetching ${SOURCE} failed: HTTP ${response.status}`);
    bytes = new Uint8Array(await response.arrayBuffer());
  }
  const digest = createHash("sha256").update(bytes).digest("hex");
  if (digest !== SHA256) throw new Error(`NormalizationTest ${DATA_VERSION} SHA-256 mismatch: ${digest}`);
  return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
}

function literal(text: string): string {
  let result = '"';
  for (let i = 0; i < text.length; i++) result += "\\u" + text.charCodeAt(i).toString(16).toUpperCase().padStart(4, "0");
  return result + '"';
}

function decode(column: string, line: number): string {
  const text = column.trim();
  if (!/^[0-9A-F]{4,6}(?: +[0-9A-F]{4,6})*$/.test(text)) throw new Error(`Malformed normalization column at line ${line}`);
  let result = "";
  for (const token of text.split(/ +/)) {
    const point = Number.parseInt(token, 16);
    if (point > 0x10ffff) throw new Error(`Out-of-range code point at line ${line}: ${token}`);
    result += String.fromCodePoint(point);
  }
  return result;
}

function parse(text: string): { header: string; rows: Row[]; listed: Set<number> } {
  const rows: Row[] = [];
  const listed = new Set<number>();
  let part = -1;
  const lines = text.split("\n");
  for (let index = 0; index < lines.length; index++) {
    const body = lines[index].split("#")[0].trim();
    if (body === "") continue;
    if (body.startsWith("@")) {
      const match = /^@Part([0-5])$/.exec(body);
      if (match === null) throw new Error(`Unexpected normalization part at line ${index + 1}`);
      const next = Number(match[1]);
      if (next !== part + 1) throw new Error(`Nonsequential normalization part at line ${index + 1}`);
      part = next;
      continue;
    }
    const fields = body.split(";");
    if (part < 0 || fields.length !== 6 || fields[5].trim() !== "") throw new Error(`Malformed normalization row at line ${index + 1}`);
    const columns: Row["columns"] = [decode(fields[0], index + 1), decode(fields[1], index + 1),
      decode(fields[2], index + 1), decode(fields[3], index + 1), decode(fields[4], index + 1)];
    rows.push({ part, line: index + 1, columns });
    if (part === 1) {
      const points = Array.from(columns[0]);
      const point = columns[0].codePointAt(0);
      if (points.length !== 1 || point === undefined) throw new Error(`Part 1 source is not one code point at line ${index + 1}`);
      listed.add(point);
    }
  }
  const marker = text.indexOf("@Part0");
  if (marker < 0 || part !== 5 || rows.length === 0) throw new Error("Incomplete normalization input");
  return { header: text.slice(0, marker), rows, listed };
}

function verifyRows(rows: Row[]): void {
  for (const row of rows) {
    const [, c2, c3, c4, c5] = row.columns;
    for (let column = 0; column < 5; column++) {
      const expected = [column < 3 ? c2 : c4, column < 3 ? c3 : c5, c4, c5];
      for (let form = 0; form < FORMS.length; form++) {
        const actual = row.columns[column].normalize(FORMS[form]);
        if (actual !== expected[form]) throw new Error(`Node disagrees with NormalizationTest ${DATA_VERSION} ` +
          `Part${row.part} line ${row.line} c${column + 1} ${FORMS[form]}: ${literal(actual)} != ${literal(expected[form])}`);
      }
    }
  }
}

function frontmatter(description: string, extra: string[] = []): string {
  return "/*---\ndescription: " + description + "\nfeatures: [" +
    ["ts-unicode-normalization", "ts-strings", "ts-iteration", "ts-arrays", ...extra].join(", ") + "]\n---*/\n" +
    `// Generated by tooling/unicode-cases/normalization.ts; Unicode ${UNICODE}, ICU ${ICU}.\n` +
    "// Contract: docs/foundations/unicode.md, Staying identical to node.\n";
}

function hex(point: number): string { return point.toString(16).toUpperCase().padStart(6, "0"); }

function sweepCases(listed: Set<number>): Map<string, string> {
  const files = new Map<string, string>();
  for (const form of FORMS) {
    for (let plane = 0; plane <= 16; plane++) {
      const start = plane * PLANE_SIZE;
      const hashes: number[] = [];
      for (let block = 0; block < 16; block++) {
        let hash = 2166136261;
        for (let point = start + block * BLOCK_SIZE; point < start + (block + 1) * BLOCK_SIZE; point++) {
          const input = String.fromCodePoint(point);
          const output = input.normalize(form);
          // Unicode's second conformance invariant also holds for unassigned
          // code points and lone surrogates in Node; check that stronger form.
          if (!listed.has(point) && output !== input) throw new Error(`NormalizationTest Part1 omits changing U+${hex(point)} for ${form}`);
          for (let unit = 0; unit < output.length; unit++) hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
        }
        hashes.push(hash);
      }
      const name = `${PREFIX}${form.toLowerCase()}-plane-${plane.toString(16).toUpperCase().padStart(2, "0")}.ts`;
      const messages = hashes.map((_, block) => `"${form} U+${hex(start + block * BLOCK_SIZE)}-U+${hex(start + (block + 1) * BLOCK_SIZE - 1)}"`);
      const source = frontmatter(`${form} agrees with Node for every code point U+${hex(start)} through U+${hex(start + PLANE_SIZE - 1)}.`, ["ts-unicode-exhaustive"]) +
        "// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.\n" +
        "// The BMP plane includes every lone surrogate U+D800-U+DFFF.\n" +
        `const expected = [${hashes.join(", ")}];\n` +
        `const blocks = [${messages.join(", ")}];\n` +
        "for (let block = 0; block < expected.length; block++) {\n" +
        "  let hash = 2166136261;\n" +
        `  const start = ${start} + block * 4096;\n` +
        "  for (let point = start; point < start + 4096; point++) {\n" +
        `    const output = String.fromCodePoint(point).normalize("${form}");\n` +
        "    for (let unit = 0; unit < output.length; unit++) {\n" +
        "      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;\n" +
        "    }\n" +
        "  }\n" +
        "  assert.sameValue(hash, expected[block], blocks[block]);\n" +
        "}\n";
      files.set(name, source);
    }
  }
  return files;
}

function conformanceCases(header: string, rows: Row[], files: Map<string, string>): number {
  let chunks = 0;
  for (let part = 0; part <= 5; part++) {
    const group = rows.filter(row => row.part === part);
    for (let offset = 0; offset < group.length; offset += CHUNK_ROWS) {
      const chunk = group.slice(offset, offset + CHUNK_ROWS);
      const first = chunk[0];
      const last = chunk[chunk.length - 1];
      const name = `${PREFIX}conformance-part-${part}-${String(offset / CHUNK_ROWS + 1).padStart(3, "0")}.ts`;
      const data = chunk.map(row => {
        const source = row.columns[0];
        // These Node-generated outputs were checked against all official
        // columns and all twenty invariants above. They also reproduce the
        // four additional source columns exactly, without duplicating data.
        const columns = [source, ...FORMS.map(form => source.normalize(form))];
        return `  [${row.line}, ${columns.map(literal).join(", ")}],`;
      }).join("\n");
      const source = frontmatter(`NormalizationTest ${DATA_VERSION} Part${part}, source lines ${first.line}-${last.line}, satisfies all twenty row invariants.`, ["ts-tuples", "ts-unicode-conformance"]) +
        `// Source: ${SOURCE}\n// SHA-256: ${SHA256}\n` +
        `// All ${chunk.length} rows in this chunk; every upstream row appears once, in its original part.\n` +
        `/*\n${header}*/\n` +
        "const rows: [number, string, string, string, string, string][] = [\n" + data + "\n];\n" +
        "for (const [line, c1, c2, c3, c4, c5] of rows) {\n" +
        "  const inputs = [c1, c2, c3, c4, c5];\n" +
        "  for (let column = 0; column < inputs.length; column++) {\n" +
        `    const label = "NormalizationTest ${DATA_VERSION} Part${part} line " + line + " c" + (column + 1);\n` +
        '    assert.sameValue(inputs[column].normalize("NFC"), column < 3 ? c2 : c4, label + " NFC");\n' +
        '    assert.sameValue(inputs[column].normalize("NFD"), column < 3 ? c3 : c5, label + " NFD");\n' +
        '    assert.sameValue(inputs[column].normalize("NFKC"), c4, label + " NFKC");\n' +
        '    assert.sameValue(inputs[column].normalize("NFKD"), c5, label + " NFKD");\n' +
        "  }\n}\n";
      files.set(name, source);
      chunks++;
    }
  }
  return chunks;
}

function writeOrCheck(files: Map<string, string>, check: boolean, output: string): void {
  const existing = existsSync(output) ? readdirSync(output).filter(name => name.startsWith(PREFIX) && name.endsWith(".ts")) : [];
  const problems: string[] = [];
  for (const name of existing) if (!files.has(name)) problems.push(`unexpected ${name}`);
  for (const [name, content] of files) {
    const path = join(output, name);
    if (existsSync(path)) {
      if (readFileSync(path, "utf8") !== content) problems.push(`differs ${name}`);
    } else if (check) problems.push(`missing ${name}`);
  }
  if (problems.length > 0) throw new Error(`Generated normalization cases disagree; existing cases were not changed:\n${problems.join("\n")}`);
  if (!check) {
    mkdirSync(output, { recursive: true });
    for (const [name, content] of files) {
      const path = join(output, name);
      if (!existsSync(path)) writeFileSync(path, content, { encoding: "utf8", flag: "wx" });
    }
  }
}

async function main(): Promise<void> {
  requireOracle();
  const config = options();
  const { header, rows, listed } = parse(await sourceText(config.dataDir));
  verifyRows(rows);
  const files = sweepCases(listed);
  const chunks = conformanceCases(header, rows, files);
  writeOrCheck(files, config.check, config.outputDir);
  console.log(JSON.stringify({ mode: config.check ? "checked" : "generated", node: NODE, unicode: UNICODE, icu: ICU,
    dataVersion: DATA_VERSION, source: SOURCE, sha256: SHA256, codePointsPerForm: 0x110000, forms: FORMS,
    blocksPerForm: 0x110000 / BLOCK_SIZE, sweepCases: 68, conformanceCases: chunks, conformanceRows: rows.length,
    conformanceAssertions: rows.length * 20, parts: Array.from({ length: 6 }, (_, part) => ({ part, rows: rows.filter(row => row.part === part).length })),
    cases: files.size }, null, 2));
}

main().catch((error: unknown) => { console.error(error instanceof Error ? error.message : String(error)); process.exitCode = 1; });
